import com.google.gson.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Generated scoped attack damage, physical Energy transfers and public zone continuations. */
public final class GeneratedRuleBatch22Test {
    static final UUID A=GeneratedRuleBatch19Test.A,B=GeneratedRuleBatch19Test.B;
    static void check(boolean b,String why){GeneratedRuleBatch8Test.check(b,why);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return GeneratedRuleBatch13Test.hand(m,p,id);}
    static AttackDefinition attack(String id,int slot){return GeneratedRuleBatch6Test.attack(id,slot);}
    static ServerMatch game(AttackDefinition a){return GeneratedRuleBatch19Test.game(a);}
    static void attach(ServerMatch m,UUID p,UUID target,String id){GeneratedRuleBatch13Test.attach(m,p,target,id);}
    static void choose(ServerMatch m,UUID target){var p=m.effectPokemonPrompt(A);m.chooseEffectPokemon(A,p.resolutionId(),p.step(),target);}
    public static void main(String[] args){benchCount();anyEnergyDamage();nextTurn();stadium();fixedCounters();remainingHp();exactKo();injuredBench();benchProtection();transfer();fullHpGuard();search();recover();drawStadium();schema();System.out.println("GeneratedRuleBatch22Test passed: typed Bench and Energy queries, scoped injured Bench damage, fixed/remaining-HP counters, exact KO, Stadium timing, unlimited physical Energy transfers, searches and recovery");}
    static void benchCount(){var a=attack("sm1_en_027",0);var m=GeneratedRuleBatch19Test.game(a,GeneratedRuleBatch19Test.plain(),List.of(),Map.of("basic",Set.of(EnergyType.FIRE,EnergyType.GRASS),"rulebox",Set.of(EnergyType.GRASS)));m.playBasicPokemonToBench(A,hand(m,A,"basic").instanceId());m.playBasicPokemonToBench(A,hand(m,A,"rulebox").instanceId());m.attack(A,a.id());check(m.lastAttack().finalDamage()==50,"Typed Bench count included Active/wrong type/opponent or doubled dual type");}
    static void anyEnergyDamage(){var a=attack("me2_en_008",0);for(boolean toBench:List.of(false,true)){var m=game(a);attach(m,A,active(m,A),"energy");attach(m,A,active(m,A),"special");attach(m,A,active(m,A),"wrong");attach(m,A,bench(m,A),"energy");UUID target=toBench?bench(m,B):active(m,B);m.attack(A,a.id(),target);check((toBench?m.benchPokemonView(B).getFirst():m.activePokemonView(B)).damage()==60,"Any-target damage counted cards, wrong type or other host");check((toBench?m.activePokemonView(B):m.benchPokemonView(B).getFirst()).damage()==0,"Any-target attack also hit unrelated target");}}
    static void nextTurn(){var a=attack("me4_en_045",0);var m=game(a);m.attack(A,a.id());check(m.lastAttack().finalDamage()==20,"Next-turn bonus applied immediately");m.endTurn(B);m.attack(A,a.id());check(m.lastAttack().finalDamage()==140,"Next-turn bonus omitted");var n=game(a);UUID first=active(n,A);n.attack(A,a.id());n.endTurn(B);n.switchActiveByEffect(A,A,bench(n,A));n.switchActiveByEffect(A,A,first);n.attack(A,a.id());check(n.lastAttack().finalDamage()==20,"Switch did not clear next-turn attack effect");}
    static void stadium(){var a=attack("me2-5_en_116",0);for(boolean present:List.of(false,true)){var t=GeneratedRuleBatch8Test.trainer("swsh5_en_138");var m=GeneratedRuleBatch19Test.game(a,t,List.of(),Map.of());CardInstance stadium=hand(m,A,"trainer");if(present)m.playTrainer(A,stadium.instanceId(),null);m.attack(A,a.id());check(m.lastAttack().finalDamage()==(present?260:120),"Stadium discarded before damage query");check(m.clientView(A).stadium()==null&&(!present||m.privateView(A).discard().contains(stadium)),"Stadium not discarded after attack");}}
    static void fixedCounters(){var a=attack("sm2_en_052",0);for(boolean toBench:List.of(false,true)){var m=game(a);m.attack(A,a.id());var p=m.effectPokemonPrompt(A);reject(()->m.chooseEffectPokemon(B,p.resolutionId(),p.step(),bench(m,B)));choose(m,toBench?bench(m,B):active(m,B));check((toBench?m.benchPokemonView(B).getFirst():m.activePokemonView(B)).damage()==10,"Single counter selected wrong Pokemon");}
        var multi=attack("sm12_en_096",1);for(boolean hasBench:List.of(false,true)){var m=game(multi);if(!hasBench)m.movePokemonByEffect(A,B,bench(m,B),LeavePlayDestination.HAND);m.attack(A,multi.id());UUID first=active(m,B);choose(m,first);if(hasBench){var q=m.effectPokemonPrompt(A);reject(()->m.chooseEffectPokemon(A,q.resolutionId(),q.step(),first));choose(m,bench(m,B));}check(m.activePokemonView(B).damage()==20&&(!hasBench||m.benchPokemonView(B).getFirst().damage()==20),"Fixed counters failed distinct targets or short field");}}
    static void remainingHp(){var a=attack("sv6_en_117",0);for(int counters:List.of(0,20,49)){var m=game(a);if(counters>0)m.placeDamageCountersByEffect(A,B,active(m,B),counters);m.attack(A,a.id());check(m.activePokemonView(B).damage()==490,"Remaining-HP counters healed or used damage instead of counters");}}
    static void exactKo(){var a=attack("me1_en_086",0);for(int counters:List.of(5,6,7)){var m=game(a);m.placeDamageCountersByEffect(A,B,active(m,B),counters);m.attack(A,a.id());check((m.phase()==MatchPhase.PRIZE_SELECTION)==(counters==6),"Exact counter KO interpreted as threshold");}}
    static void injuredBench(){var a=attack("sv3-5_en_145",0);for(boolean injured:List.of(false,true)){var m=game(a);UUID target=bench(m,B);m.endTurn(A);m.playBasicPokemonToBench(B,hand(m,B,"basic").instanceId());m.endTurn(B);m.placeDamageCountersByEffect(A,B,active(m,B),1);if(injured)m.placeDamageCountersByEffect(A,B,target,1);m.attack(A,a.id());if(injured){var p=m.effectPokemonPrompt(A);check(p.targets().size()==1&&p.targets().getFirst().pokemonId().equals(target),"Injured Bench filter admitted Active or undamaged Pokemon");reject(()->m.chooseEffectPokemon(A,p.resolutionId(),p.step(),active(m,B)));reject(()->m.chooseEffectPokemon(B,p.resolutionId(),p.step(),target));choose(m,target);}check(m.activePokemonView(B).damage()==130&&m.benchPokemonView(B).getFirst().damage()==(injured?100:0)&&m.benchPokemonView(B).getLast().damage()==0,"Scoped Bench damage selected wrong Pokemon or no-target flow stalled");check(!m.hasPendingEffectChoice(),"No matching Bench target stalled attack");}
        var m=game(a);UUID victim=bench(m,B);m.placeDamageCountersByEffect(A,B,victim,42);m.attack(A,a.id());choose(m,victim);check(m.phase()==MatchPhase.PRIZE_SELECTION&&m.benchPokemonView(B).isEmpty(),"Bench attack damage failed KO/prize checkpoint");
    }
    static void benchProtection(){var a=attack("sv3-5_en_145",0);var guard=GeneratedRuleBatch8Test.ability("sm10_en_076");for(boolean disabled:List.of(false,true)){var m=GeneratedRuleBatch19Test.game(a,GeneratedRuleBatch19Test.plain(),List.of(guard),Map.of());UUID victim=bench(m,B);m.disableAbilityEffectsByEffect(A,B,active(m,B));if(disabled)m.disableAbilityEffectsByEffect(A,B,victim);m.placeDamageCountersByEffect(A,B,victim,1);m.attack(A,a.id());choose(m,victim);check(m.benchPokemonView(B).getFirst().damage()==(disabled?100:10),"Scoped Bench damage bypassed live attack protection or suppression");}}
    static void transfer(){var a=GeneratedRuleBatch8Test.ability("sm1_en_141");var m=GeneratedRuleBatch8Test.fixture(List.of(a),EnergyType.PSYCHIC,EnergyType.GRASS);UUID source=active(m,A),target=bench(m,A);attach(m,A,source,"special");attach(m,A,source,"wrong");attach(m,B,active(m,B),"energy");for(int i=0;i<2;i++){UUID from=i==0?source:target,to=i==0?target:source;m.useAbility(A,target,a.id());var p=m.effectCardPrompt(A);check(p.candidates().size()==1&&p.candidates().getFirst().definitionId().equals("special"),"Transfer candidates wrong owner/type");UUID energy=p.candidates().getFirst().instanceId();m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(energy));var q=m.effectAttachmentPrompt(A);check(!q.targets().contains(from),"Transfer allowed same source destination");reject(()->m.chooseEffectAttachmentTarget(B,q.resolutionId(),q.step(),to));m.chooseEffectAttachmentTarget(A,q.resolutionId(),q.step(),to);}check(m.activePokemonView(A).attachedEnergyIds().size()==2&&!m.energyAttached(A),"Unlimited transfer spent manual attachment or duplicated multi-unit card");}
    static void fullHpGuard(){var a=GeneratedRuleBatch8Test.ability("xy4_en_050");for(boolean injured:List.of(false,true)){var m=GeneratedRuleBatch19Test.game(GeneratedRuleBatch8Test.hit(100,false),GeneratedRuleBatch19Test.plain(),List.of(a),Map.of());if(injured)m.placeDamageCountersByEffect(A,B,active(m,B),1);m.attack(A,"hit");check(m.lastAttack().finalDamage()==(injured?100:50),"Full-HP guard read post-damage HP");}}
    static void search(){for(var id:List.of("sv1_en_138","sv2_en_047","me5-5_en_076")){var a=attack(id,0);var t=GeneratedRuleBatch8Test.trainer(id.equals("me5-5_en_076")?"swsh5_en_138":"xy2_en_093");var m=GeneratedRuleBatch19Test.game(a,t,List.of(),Map.of());m.attack(A,a.id());if(m.hasPendingEffectChoice()){var p=m.effectCardPrompt(A);check(p.minimum()==0&&p.maximum()==(id.equals("sv1_en_138")?3:2)&&p.candidates().stream().allMatch(c->c.definitionId().equals(id.equals("sv1_en_138")?"tool":"trainer")),"Search lost category or hidden-deck optionality "+id+" "+p);m.submitEffectCards(A,p.resolutionId(),p.step(),List.of());}check(!m.hasPendingEffectChoice(),"Declined hidden search stalled");}}
    static void recover(){var a=attack("sm11_en_119",0);var m=game(a);var ids=List.of(hand(m,A,"wrong").instanceId(),hand(m,A,"tool").instanceId());m.discardHandCardsByEffect(A,A,ids);int deck=m.privateView(A).deck().size();m.attack(A,a.id());var p=m.effectCardPrompt(A);check(p.minimum()==2&&p.maximum()==4,"Mandatory four-card recovery did not clamp minimum to available two "+p);reject(()->m.submitEffectCards(A,p.resolutionId(),p.step(),ids.subList(0,1)));m.submitEffectCards(A,p.resolutionId(),p.step(),ids);check(m.privateView(A).discard().isEmpty()&&m.privateView(A).deck().size()==deck+2,"Recovery sent cards to wrong zone");}
    static void drawStadium(){for(String id:List.of("swsh12_en_167","xy7_en_079")){var m=GeneratedRuleBatch19Test.trainer(id);int hand=m.privateView(A).hand().size();m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);check(m.privateView(A).hand().size()==hand-1+(id.startsWith("swsh")?3:1),"Absent Stadium prevented independent draw");}}
    static void schema(){String child="{\"type\":\"bench_damage\",\"target\":\"CHOSEN_POKEMON\",\"amount\":90}";for(String position:List.of("ANY","ACTIVE"))reject(()->AttackProgramRules.validate(BeforeDamageAttackTest.attack("","","{\"type\":\"select_pokemon\",\"target\":\"SELECT_OPPONENT_POKEMON\",\"position\":\""+position+"\",\"effects\":["+child+"]}")));reject(()->AttackProgramRules.validate(BeforeDamageAttackTest.attack("","",child)));}
}
